function uid(p) { return p + '-' + Math.random().toString(36).slice(2, 8); }
function esc(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }
function fmtDate(iso) {
  if (!iso) return '—';
  return new Date(iso).toLocaleString('es-CO', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' });
}
function fmtRel(iso) {
  if (!iso) return '—';
  const d = new Date(iso), now = new Date();
  const startOfDay = x => new Date(x.getFullYear(), x.getMonth(), x.getDate());
  const diff = Math.round((startOfDay(d) - startOfDay(now)) / 86400000);
  const time = d.toLocaleTimeString('es-CO', { hour:'numeric', minute:'2-digit' });
  if (diff === 0) return 'Hoy ' + time;
  if (diff === 1) return 'Mañana ' + time;
  if (diff === -1) return 'Ayer ' + time;
  return d.toLocaleDateString('es-CO', { day:'2-digit', month:'short' }) + ' ' + time;
}
function pillClass(estado) {
  const verdes = ['activo','activa','Publicada','publicada','revisada','emitido','Calificada','Participó'];
  const ambar = ['borrador','Borrador','inactivo','inactiva','entregada','Pendiente de calificar','Pendiente calificar'];
  const azul = ['programada','programado','en_curso'];
  const gris = ['archivado','archivada','cerrado','finalizado','finalizada'];
  const clay = ['cancelado','rechazada','anulado','Sin entregar','Sin participar'];
  if (typeof estado === 'string' && estado.endsWith('%')) {
    const pct = parseFloat(estado);
    return pct >= 80 ? 'pill-verde' : pct >= 60 ? 'pill-ambar' : 'pill-clay';
  }
  if (verdes.includes(estado)) return 'pill-verde';
  if (ambar.includes(estado)) return 'pill-ambar';
  if (azul.includes(estado)) return 'pill-azul';
  if (gris.includes(estado)) return 'pill-gris';
  if (clay.includes(estado)) return 'pill-clay';
  return 'pill-gris';
}
function pill(estado) {
  const texto = String(estado).replace(/_/g, ' ');
  const capitalizado = texto.charAt(0).toUpperCase() + texto.slice(1);
  return '<span class="pill ' + pillClass(estado) + '">' + esc(capitalizado) + '</span>';
}

